public class NamespaceDetector extends Detector implements XmlScanner {
    private static final Implementation IMPLEMENTATION = new Implementation(NamespaceDetector.class, Scope.RESOURCE_FILE_SCOPE);
    public static final Issue ISSUE = Issue.create("LibraryCustomView", "Library custom views should use res-auto namespace", "...", Category.CORRECTNESS, 6, Severity.WARNING, IMPLEMENTATION);
    private static final String AUTO_URI = SdkConstants.AUTO_URI; // http://schemas.android.com/apk/res-auto
    @Override
    public Collection<String> getApplicableElements() { return XmlScannerConstants.ALL; }
    @Override
    public void visitElement(@NonNull XmlContext context, @NonNull Element element) {
        if (!context.getProject().isLibrary()) return;
        String tag = element.getTagName();
        if (!tag.contains(".")) return;
        ResourceFolderType type = ResourceFolderType.getFolderType(context.file.getParentFile().getName());
        if (type != ResourceFolderType.LAYOUT) return;
        String pkg = context.getProject().getPackage();
        if (pkg == null) return;
        String pkgUri = "http://schemas.android.com/apk/res/" + pkg;
        for (int i=0; i<element.getAttributes().getLength(); i++) {
            Node node = element.getAttributes().item(i);
            if (node.getNodeType() != Node.ATTRIBUTE_NODE) continue;
            Attr attr = (Attr) node;
            String ns = attr.getNamespaceURI();
            if (pkgUri.equals(ns)) {
                String prefix = attr.getPrefix();
                if (prefix != null) {
                    // find declaration
                    Element curr = element;
                    while (curr != null) {
                        String xmlns = "xmlns:" + prefix;
                        Attr nsAttr = curr.getAttributeNode(xmlns);
                        if (nsAttr != null && pkgUri.equals(nsAttr.getValue())) {
                            // report
                        }
                        curr = curr.getParentNode() instanceof Element ? (Element)curr.getParentNode() : null;
                    }
                }
            }
        }
    }
}
```

